#!/usr/bin/env python3
"""Souriau thermodynamics for the zeta symmetry chart.

This verifies the algebra mirrored by
`InfoGeometry.Arithmetic.ZetaSouriauSymmetryThermodynamics`:

* the exact zeta chart frame is the Klein four generated by conjugation and
  functional reflection;
* the centered chart has a semidirect `R ⋊ V4` action through height
  translations;
* the linear Souriau pairing is invariant under the exact finite frame;
* the displacement Gibbs energy is invariant under the full finite-by-real
  chart action.

No numerical zeta values or RH claims are used here.
"""

from __future__ import annotations

import sympy as sp


u, v, bu, bv, a, b, c = sp.symbols("u v bu bv a b c", real=True)
u2, v2 = sp.symbols("u2 v2", real=True)
m1u, m1v, m2u, m2v = sp.symbols("m1u m1v m2u m2v", real=True)

Point = tuple[sp.Expr, sp.Expr]


def same(p: Point, q: Point) -> bool:
    return all(sp.simplify(x - y) == 0 for x, y in zip(p, q, strict=True))


def add(p: Point, q: Point) -> Point:
    return (p[0] + q[0], p[1] + q[1])


def flat_displacement(p: Point, q: Point) -> sp.Expr:
    return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2


def pairing(beta: Point, moment: Point) -> sp.Expr:
    return beta[0] * moment[0] + beta[1] * moment[1]


frames = ("id", "C", "F", "J")


def compose_frame(g: str, h: str) -> str:
    table = {
        ("id", "id"): "id",
        ("id", "C"): "C",
        ("id", "F"): "F",
        ("id", "J"): "J",
        ("C", "id"): "C",
        ("F", "id"): "F",
        ("J", "id"): "J",
        ("C", "C"): "id",
        ("F", "F"): "id",
        ("J", "J"): "id",
        ("C", "F"): "J",
        ("F", "C"): "J",
        ("C", "J"): "F",
        ("J", "C"): "F",
        ("F", "J"): "C",
        ("J", "F"): "C",
    }
    return table[(g, h)]


def sign(g: str) -> int:
    return 1 if g in {"id", "J"} else -1


def frame_act(g: str, p: Point) -> Point:
    x, y = p
    if g == "id":
        return (x, y)
    if g == "C":
        return (x, -y)
    if g == "F":
        return (-x, -y)
    if g == "J":
        return (-x, y)
    raise ValueError(g)


def height(t: sp.Expr, p: Point) -> Point:
    return (p[0], p[1] + t)


def semidirect_compose(left: tuple[str, sp.Expr], right: tuple[str, sp.Expr]) -> tuple[str, sp.Expr]:
    g, t = left
    h, s = right
    return (compose_frame(g, h), t + sign(g) * s)


def semidirect_inverse(element: tuple[str, sp.Expr]) -> tuple[str, sp.Expr]:
    g, t = element
    return (g, -sign(g) * t)


def semidirect_act(element: tuple[str, sp.Expr], p: Point) -> Point:
    g, t = element
    return height(t, frame_act(g, p))


def assert_expr_zero(expr: sp.Expr, label: str) -> None:
    if sp.simplify(expr) != 0:
        raise AssertionError((label, sp.factor(expr)))


def chart_potential_cocycle(phi: sp.Function, element: tuple[str, sp.Expr], p: Point) -> sp.Expr:
    moved = semidirect_act(element, p)
    return phi(*moved) - phi(*p)


def main() -> None:
    x = (u, v)
    y = (u2, v2)
    beta = (bu, bv)
    m1 = (m1u, m1v)
    m2 = (m2u, m2v)

    for g in frames:
        for h in frames:
            assert sign(compose_frame(g, h)) == sign(g) * sign(h)
            assert same(frame_act(compose_frame(g, h), x), frame_act(g, frame_act(h, x)))

    for g in frames:
        assert same(frame_act(g, height(a, x)), height(sign(g) * a, frame_act(g, x)))
        assert_expr_zero(
            flat_displacement(frame_act(g, x), frame_act(g, y)) - flat_displacement(x, y),
            f"finite displacement invariance {g}",
        )
        assert_expr_zero(
            pairing(frame_act(g, beta), frame_act(g, x)) - pairing(beta, x),
            f"linear pairing invariance {g}",
        )

    elements = [(g, t) for g in frames for t in (a, b, c)]
    for g in frames:
        for h in frames:
            left = (g, a)
            right = (h, b)
            composed = semidirect_compose(left, right)
            assert same(semidirect_act(composed, x), semidirect_act(left, semidirect_act(right, x)))

    for g in frames:
        element = (g, a)
        inv = semidirect_inverse(element)
        assert semidirect_compose(inv, element)[0] == "id"
        assert_expr_zero(semidirect_compose(inv, element)[1], f"left inverse {g}")
        assert semidirect_compose(element, inv)[0] == "id"
        assert_expr_zero(semidirect_compose(element, inv)[1], f"right inverse {g}")
        assert_expr_zero(
            flat_displacement(semidirect_act(element, x), semidirect_act(element, y))
            - flat_displacement(x, y),
            f"full displacement invariance {g}",
        )

    # General thermodynamic 1-cocycle for any chart potential:
    # c(AB, β) = c(A, Bβ) + c(B, β), with action (AB)β = A(Bβ).
    phi = sp.Function("Phi")
    for g in frames:
        for h in frames:
            left = (g, a)
            right = (h, b)
            composed = semidirect_compose(left, right)
            beta_after_right = semidirect_act(right, beta)
            cocycle_law = (
                chart_potential_cocycle(phi, composed, beta)
                - chart_potential_cocycle(phi, left, beta_after_right)
                - chart_potential_cocycle(phi, right, beta)
            )
            assert_expr_zero(cocycle_law, f"potential cocycle law {g},{h}")

    # Finite linear Souriau partition: simultaneous exact V4 transform leaves
    # each Boltzmann exponent unchanged.
    for g in frames:
        e1 = pairing(frame_act(g, beta), frame_act(g, m1))
        e2 = pairing(frame_act(g, beta), frame_act(g, m2))
        assert_expr_zero(e1 - pairing(beta, m1), f"linear partition exponent 1 {g}")
        assert_expr_zero(e2 - pairing(beta, m2), f"linear partition exponent 2 {g}")

    # Full chart/Killing partition: displacement energies are invariant under
    # the finite-by-real action.
    for g in frames:
        element = (g, a)
        e1 = flat_displacement(semidirect_act(element, beta), semidirect_act(element, m1))
        e2 = flat_displacement(semidirect_act(element, beta), semidirect_act(element, m2))
        assert_expr_zero(e1 - flat_displacement(beta, m1), f"displacement exponent 1 {g}")
        assert_expr_zero(e2 - flat_displacement(beta, m2), f"displacement exponent 2 {g}")

        z_original = sp.exp(-flat_displacement(beta, m1)) + sp.exp(-flat_displacement(beta, m2))
        z_transformed = sp.exp(-e1) + sp.exp(-e2)
        assert_expr_zero(z_transformed - z_original, f"displacement partition cocycle zero {g}")

    print("zeta_souriau_symmetry_thermodynamics: ok")
    print("  exact_frame: V4 = {id, C, F, J}")
    print("  chart_lie_shadow: R ⋊ V4 with height sign character")
    print("  potential_cocycle: c(AB,beta)=c(A,Bbeta)+c(B,beta)")
    print("  finite_linear_pairing: invariant under exact V4")
    print("  displacement_partition: invariant under full chart/Killing action")
    print(f"  sample_linear_energy: {pairing(beta, x)}")
    print(f"  sample_displacement_energy: {flat_displacement(beta, x)}")


if __name__ == "__main__":
    main()
